663	func TestConcurrentVotingAndTally(t *testing.T) {
664		store, _ := openTempStore(t, 1000)
665		defer store.Close()
666		in := baseVoteInput("gip-conc")
667		mustCreateVote(t, store, in)
668	
669		// 两名代表在同一时刻反复投同一选择；只能各成功一次且票据不重复。
670		var wg sync.WaitGroup
671		errs := make(chan error, 64)
672		start := make(chan struct{})
673		vote := func(voter string, support bool, now int64) {
674			defer wg.Done()
675			<-start
676			if _, err := store.CastVote("gip-conc", voter, support, int64(now)); err != nil {
677				errs <- err
678			}
679		}
680		for i := 0; i < 16; i++ {
681			wg.Add(2)
682			go vote("alice", true, 150)
683			go vote("dave", false, 150)
684		}
685		close(start)
686		wg.Wait()
687		close(errs)
688		for err := range errs {
689			t.Errorf("concurrent identical vote: %v", err)
690		}
691		v, _, _ := store.VoteProposal("gip-conc")
692		if len(v.Ballots) != 2 {
693			t.Fatalf("ballot count=%d, want 2", len(v.Ballots))
694		}
695	
696		// 计票与投票并发：只有先于计票成功的票进入结论；二者由同一把锁串行。
697		in2 := baseVoteInput("gip-conc2")
698		in2.Quorum = 1000
699		mustCreateVote(t, store, in2)
700		var wg2 sync.WaitGroup
701		start2 := make(chan struct{})
702		wg2.Add(1)
703		go func() { // 迟到的票：可能在计票前或后
704			defer wg2.Done()
705			<-start2
706			_, _ = store.CastVote("gip-conc2", "dave", false, 150)
707		}()
708		wg2.Add(1)
709		go func() {
710			defer wg2.Done()
711			<-start2
712			_, _ = store.TallyVote("gip-conc2", 200)
713		}()
714		close(start2)
715		wg2.Wait()
716		v2, _, _ := store.VoteProposal("gip-conc2")
717		if v2.Tally == nil {
718			t.Fatal("proposal not tallied")
719		}
720		// 结论必须能由已保存票据重放（打开/提交时的严格校验兜底；这里再显式断言）。
721		var forW, againstW int64
722		for _, b := range v2.Ballots {
723			if b.Support {
724				forW += b.Weight
725			} else {
726				againstW += b.Weight
727			}
728		}
729		if forW != v2.Tally.ForWeight || againstW != v2.Tally.AgainstWeight {
730			t.Fatalf("tally %+v inconsistent with ballots for=%d against=%d", v2.Tally, forW, againstW)
731		}
732	}
