906					}
907					t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
908				}
909				if got, rerr := os.ReadFile(bad); rerr != nil || string(got) != string(raw) {
910					t.Fatalf("corrupt file was modified")
911				}
912			})
913		}
914	}
