1576	// TestExplicitFalseAndZeroBallotLegal：明确写出的 false 是有效反对票，
1577	// 投票窗口从 0 开始时明确写出的 0 是有效首次投票时间，二者都不得当成缺失。
1578	// 空票据列表的未投票提案同样继续可读、可计票。
1579	func TestExplicitFalseAndZeroBallotLegal(t *testing.T) {
1580		dir := t.TempDir()
1581		handwritten := filepath.Join(dir, "handwritten.json")
1582		// 手工构造：start=0、票据 support=false、voted_at=0，quorum=1。
1583		raw := `{
1584	  "magic": "govflow-treasury-state",
1585	  "version": 1,
1586	  "initial_treasury": 1000,
1587	  "treasury": 1000,
1588	  "balances": {},
1589	  "proposals": {},
1590	  "receipts": [],
1591	  "vote_proposals": {
1592	    "gip-fz": {
1593	      "id": "gip-fz",
1594	      "state": "voting",
1595	      "members": [{"id": "a", "weight": 5}, {"id": "b", "weight": 5}],
1596	      "delegations": [],
1597	      "quorum": 1,
1598	      "start_at": 0,
1599	      "deadline": 10,
1600	      "timelock_end": 10,
1601	      "actions": [],
1602	      "ballots": [{"representative": "b", "weight": 5, "support": false, "voted_at": 0}]
1603	    }
1604	  }
1605	}
1606	`
1607		if err := os.WriteFile(handwritten, []byte(raw), 0o600); err != nil {
1608			t.Fatal(err)
1609		}
1610		s, err := Open(handwritten)
