1683	// TestIncompleteTallyRejectedAsCorrupt：已计票提案的计票结果缺少 for_weight 或
1684	// against_weight（或为 null、JSON 类型不符）时，整份状态文件判为损坏——即使缺失
1685	// 一侧的真实票重恰好为零、逐票明细能重放出相同结论，也不得默认补零后接受。
1686	// 已通过、已拒绝、已执行的提案遵守同一条完整性规则。错误必须能看出提案编号、
1687	// 缺失字段与原因分类，且原文件保留。
1688	func TestIncompleteTallyRejectedAsCorrupt(t *testing.T) {
1689		dir := t.TempDir()
1690		path := filepath.Join(dir, "treasury.json")
1691		store, err := InitTreasury(path, 1000)
1692		if err != nil {
1693			t.Fatal(err)
1694		}
1695		// 三项提案共用同一份名单（quorum=600，alice 归集 600，dave 400）：
1696		// gip-passed：alice 600 赞成、反对 0，恰好达到法定人数而通过；
1697		// gip-rejected：dave 400 反对、赞成 0，参与不足而拒绝；
1698		// gip-executed：与 gip-passed 相同并已在时间锁后执行。
1699		passed := baseVoteInput("gip-passed")
1700		mustCreateVote(t, store, passed)
1701		rejected := baseVoteInput("gip-rejected")
1702		mustCreateVote(t, store, rejected)
1703		executed := baseVoteInput("gip-executed")
1704		mustCreateVote(t, store, executed)
1705		for _, id := range []string{"gip-passed", "gip-rejected", "gip-executed"} {
1706			voter, support := "alice", true
1707			if id == "gip-rejected" {
1708				voter, support = "dave", false
1709			}
1710			if _, err := store.CastVote(id, voter, support, 150); err != nil {
1711				t.Fatal(err)
1712			}
1713			if _, err := store.TallyVote(id, 200); err != nil {
1714				t.Fatal(err)
1715			}
1716		}
1717		if _, err := store.Execute("gip-executed", 300); err != nil {
1718			t.Fatal(err)
1719		}
1720		store.Close()
1721	
1722		good, err := os.ReadFile(path)
1723		if err != nil {
1724			t.Fatal(err)
1725		}
1726		// mutate 以结构化改写构造损坏变体；id 标明出问题的提案。
1727		mutate := func(id string, fn func(tally map[string]any)) []byte {
1728			var clone map[string]any
1729			if err := json.Unmarshal(good, &clone); err != nil {
1730				t.Fatal(err)
1731			}
1732			p := clone["vote_proposals"].(map[string]any)[id].(map[string]any)
1733			fn(p["tally"].(map[string]any))
1734			raw, err := json.MarshalIndent(clone, "", "  ")
1735			if err != nil {
1736				t.Fatal(err)
1737			}
1738			return append(raw, '\n')
1739		}
1740		cases := map[string]struct {
1741			raw       []byte
1742			id        string
1743			field     string
1744			causeWord string
1745		}{
1746			// 标题场景：赞成 600/反对 0/法定人数 600 已通过，反对权重被删掉。
1747			"against weight missing on passed zero side": {
1748				mutate("gip-passed", func(tl map[string]any) { delete(tl, "against_weight") }),
1749				"gip-passed", "against_weight", "missing",
1750			},
1751			"for weight missing on passed": {
1752				mutate("gip-passed", func(tl map[string]any) { delete(tl, "for_weight") }),
1753				"gip-passed", "for_weight", "missing",
1754			},
1755			// 已拒绝提案的赞成侧恰好为零，同样不得补零接受。
1756			"for weight missing on rejected zero side": {
1757				mutate("gip-rejected", func(tl map[string]any) { delete(tl, "for_weight") }),
1758				"gip-rejected", "for_weight", "missing",
1759			},
1760			// 已执行提案的首次计票记录同样必须完整。
1761			"against weight missing on executed": {
1762				mutate("gip-executed", func(tl map[string]any) { delete(tl, "against_weight") }),
1763				"gip-executed", "against_weight", "missing",
1764			},
1765			"for weight null": {
1766				mutate("gip-passed", func(tl map[string]any) { tl["for_weight"] = nil }),
1767				"gip-passed", "for_weight", "null",
1768			},
1769			"against weight null": {
1770				mutate("gip-rejected", func(tl map[string]any) { tl["against_weight"] = nil }),
1771				"gip-rejected", "against_weight", "null",
1772			},
1773			"for weight string not integer": {
1774				mutate("gip-passed", func(tl map[string]any) { tl["for_weight"] = "600" }),
1775				"gip-passed", "for_weight", "wrong type",
1776			},
1777			"against weight float not integer": {
1778				mutate("gip-passed", func(tl map[string]any) { tl["against_weight"] = 0.5 }),
1779				"gip-passed", "against_weight", "wrong type",
1780			},
1781			"for weight boolean not integer": {
1782				mutate("gip-passed", func(tl map[string]any) { tl["for_weight"] = true }),
1783				"gip-passed", "for_weight", "wrong type",
1784			},
1785			"against weight over int64": {
1786				mutate("gip-passed", func(tl map[string]any) { tl["against_weight"] = 9223372036854775808.0 }),
1787				"gip-passed", "against_weight", "wrong type",
1788			},
1789		}
1790		for name, tc := range cases {
1791			t.Run(name, func(t *testing.T) {
1792				bad := filepath.Join(dir, "bad-"+strings.ReplaceAll(name, " ", "-")+".json")
1793				if err := os.WriteFile(bad, tc.raw, 0o600); err != nil {
1794					t.Fatal(err)
1795				}
1796	
1797				// 打开即拒绝，错误带提案编号、计票字段与原因分类。
1798				s, err := Open(bad)
1799				if !errors.Is(err, ErrStateCorrupt) {
1800					if s != nil {
1801						s.Close()
1802					}
1803					t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
1804				}
1805				msg := err.Error()
1806				for _, want := range []string{`"` + tc.id + `"`, "tally", `"` + tc.field + `"`, tc.causeWord} {
1807					if !strings.Contains(msg, want) {
1808						t.Fatalf("error %q missing %q", msg, want)
1809					}
1810				}
1811	
1812				// 原文件内容必须原样保留（失败不回写、不把缺失权重补成 0）。
1813				if got, rerr := os.ReadFile(bad); rerr != nil || string(got) != string(tc.raw) {
1814					t.Fatalf("corrupt file was modified on rejected Open")
1815				}
1816	
1817				// 重复打开仍以同一损坏分类拒绝，绝不返回可用句柄给出部分结果。
1818				s2, e := Open(bad)
1819				if !errors.Is(e, ErrStateCorrupt) {
1820					if s2 != nil {
1821						s2.Close()
1822					}
1823					t.Fatalf("reopen err=%v, want ErrStateCorrupt", e)
1824				}
1825			})
1826		}
1827	}
